"function exportHistory(){var csv='Time,Result,Profit,Balance\\n';for(var i=0;i<historyData.length;i++){var h=historyData[i];csv+=h.time+','+h.result+','+h.profit+','+h.bal+'\\n';}var blob=new Blob([csv],{type:'text/csv'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='sona_v33_history.csv';a.click();}",
